parameters.jsonBody:
={{ (() => {
  const cfg = $('Fetch Tenant AI Config').item.json;
  const textBinding = cfg.provider_bindings?.text;
  if (!textBinding?.provider_code || !textBinding?.model_code) {
    throw new Error('TEXT_LANE_BINDING_MISSING');
  }

  let contentPayload = $json.prompt;
  const imgRegex = /!\[.*?\]\(([^)\s]+)\)/g;
  const matches = [...$json.prompt.matchAll(imgRegex)];

  if (matches.length > 0) {
    const contentArray = [];
    let lastIndex = 0;
    for (const match of matches) {
      const textPart = $json.prompt.substring(lastIndex, match.index);
      if (textPart.trim()) contentArray.push({ type: "text", text: textPart });
      let url = match[1];
      if (url.startsWith('/')) url = 'https://agent.pnmediaplus.com' + url;
      contentArray.push({ type: "image_url", image_url: { url: url } });
      lastIndex = match.index + match[0].length;
    }
    const remaining = $json.prompt.substring(lastIndex);
    if (remaining.trim()) contentArray.push({ type: "text", text: remaining });
    contentPayload = contentArray;
  }

  return {
    provider: textBinding.provider_code,
    model: textBinding.model_code,
    messages: [{ role: 'user', content: contentPayload }],
    response_format: { type: 'json_object' },
    tenant_id: $json.tenant_id,
    lane_key: 'text',
    tenant_binding_id: cfg.tenant_binding_id || ''
  };
})() }}

