const responseText = $input.first().json.choices?.[0]?.message?.content || '{}';
const item = $('Format Prompt').item.json.item;
const tenant_id = $('Format Prompt').item.json.tenant_id;
let parsed = {};
try {
  parsed = JSON.parse(responseText);
} catch(e) {
  throw new Error('AI Response was not valid JSON');
}

const researchPacket = typeof parsed.agent_1_research_packet === 'string' ? parsed.agent_1_research_packet.trim() : '';
const captionPacket = typeof parsed.agent_2_publish_ready_caption === 'string' ? parsed.agent_2_publish_ready_caption.trim() : '';
const imagePrompt = typeof parsed.agent_3_image_prompt === 'string' ? parsed.agent_3_image_prompt.trim() : '';
if (!researchPacket) {
  throw new Error('RESEARCH_PACKET_MISSING');
}
if (!captionPacket) {
  throw new Error('CAPTION_PACKET_MISSING');
}
if (!imagePrompt) {
  throw new Error('IMAGE_PROMPT_MISSING');
}

return { 
  json: { 
    id: item.id, 
    organization_id: item.organization_id,
    tenant_id: tenant_id,
    textContent: {
      agent_1_research_packet: researchPacket,
      agent_2_publish_ready_caption: captionPacket,
      agent_3_image_prompt: imagePrompt
    },
    item: item
  } 
};

const ideaItem = $('Get Item (Webhook)').item.json[0] || $('Get Item (Webhook)').item.json;
const govData = $('Fetch Governance Registry').item.json.data;
const webhookBody = $('Webhook Trigger').first().json.body || $('Webhook Trigger').first().json;
const qa_retry_count = webhookBody.qa_retry_count || 0;
const qa_feedback = webhookBody.qa_feedback || '';


if (!ideaItem) {
  throw new Error('CONTENT_ITEM_NOT_FOUND');
}

// Find agents
const agent1 = govData.agents.find(a => a.role_id === 'marketing_agent_1_viral_research_angle');
const agent2 = govData.agents.find(a => a.role_id === 'marketing_agent_2_social_caption_architect');
const agent3 = govData.agents.find(a => a.role_id === 'marketing_agent_3_image_prompt_architect');

if (!agent1 || !agent2 || !agent3) {
  throw new Error('MARKETING_AGENT_REGISTRY_INCOMPLETE');
}

if (!agent1.capability_boundary || !agent2.capability_boundary || !agent3.capability_boundary) {
  throw new Error('MARKETING_AGENT_CAPABILITY_BOUNDARY_MISSING');
}

const imgMatch = (ideaItem.brief || '').match(/!\[.*?\]\(([^)\s]+)\)/);
let providedImageUrl = imgMatch ? imgMatch[1] : null;
if (providedImageUrl && providedImageUrl.startsWith('/')) {
   providedImageUrl = 'https://agent.pnmediaplus.com' + providedImageUrl;
}

const prompt = `You are an orchestration of 3 specialized AI Marketing Agents working in sequence.
You MUST respect the capabilities (MUST) and strictly avoid the prohibitions (MUST NOT) of each agent.
The governance rules are currently in DRAFT_METADATA_ONLY mode.

[AGENT 1: VIRAL RESEARCH ANGLE]
MUST: ${agent1.capability_boundary.must.join(', ')}
MUST NOT: ${agent1.capability_boundary.must_not.join(', ')}

[AGENT 2: SOCIAL CAPTION ARCHITECT]
MUST: ${agent2.capability_boundary.must.join(', ')}
MUST NOT: ${agent2.capability_boundary.must_not.join(', ')}

[AGENT 3: IMAGE PROMPT ARCHITECT]
MUST: ${agent3.capability_boundary.must.join(', ')}
MUST NOT: ${agent3.capability_boundary.must_not.join(', ')}

---
Idea Title: ${ideaItem.title}${qa_retry_count > 0 ? '\n\n[QA FEEDBACK FROM PREVIOUS RUN - MUST FIX]\n' + qa_feedback : ''}
Brief: ${ideaItem.brief || 'No brief provided.'}\n${providedImageUrl ? '\n[SYSTEM NOTE: The human has provided an image (' + providedImageUrl + '). Agent 1, Agent 2, AND Agent 3 MUST deeply analyze this image and use it as the primary visual context. Do NOT hallucinate things not in the image.]' : ''}

IMPORTANT LANGUAGE & CONTEXT INSTRUCTION:

- You MUST write "agent_1_research_packet" and "agent_2_publish_ready_caption" entirely in natural, fluent Vietnamese (Tiếng Việt).

AGENT 1 — RESEARCH & VIRAL ANGLE:
- "agent_1_research_packet" must provide a concise but meaningful analysis of:
  1. the core topic or event;
  2. the most interesting audience insight;
  3. the strongest social-media angle;
  4. why people may stop, comment, share, or relate to it;
  5. factual boundaries — what is known versus uncertain;
  6. the recommended hook direction;
  7. the recommended visual direction.
- Prioritize useful insights over generic summaries.
- Do NOT invent facts, statistics, quotes, trends, names, dates, or claims.

AGENT 2 — PUBLISH-READY SOCIAL CAPTION:
- For "agent_2_publish_ready_caption", act as a top-tier Vietnamese Social Media Copywriter.
- The caption MUST feel human, contemporary, engaging, and publication-ready.
- Do NOT write generic, robotic, overly formal, or short/abrupt copy.
- Start with a strong scroll-stopping hook.
- Build curiosity, relatability, emotion, humor, tension, or useful insight where appropriate to the topic.
- Use relevant emojis strategically. Do not spam emojis.
- Use natural conversational Vietnamese suitable for social media.
- Encourage meaningful interaction such as comments, tagging, sharing, or discussion where appropriate.
- End with one clear Call-to-Action.
- Avoid clickbait that misrepresents the actual content.

FACTUAL INTEGRITY CONSTRAINT:
- "agent_2_publish_ready_caption" MUST be based only on information supported by the provided input and "agent_1_research_packet".
- Never fabricate statistics, facts, quotes, events, names, dates, prices, trends, or claims for the sake of engagement.
- Creativity is allowed in wording, storytelling, hooks, humor, emotional framing, and CTA — never in factual claims.
- If a factual detail is uncertain, omit it rather than invent it.

CROSS-AGENT CONSISTENCY:
- "agent_2_publish_ready_caption" MUST use the strongest social angle identified in "agent_1_research_packet".
- "agent_3_image_prompt" MUST visually communicate the same core idea, hook, emotional tone, and audience context as the caption.
- All three outputs must form ONE coherent social-media creative concept.

JSON ESCAPING CONSTRAINT:
- "agent_2_publish_ready_caption" MUST NOT contain unescaped raw line-break characters inside the JSON string.
- Represent intended paragraph breaks using the standard JSON escape sequence (\\n).
- Properly escape all double quotes and other JSON-sensitive characters.
- The final response MUST remain parseable as strict JSON.

AGENT 3 — IMAGE PROMPT:
- "agent_3_image_prompt" MUST be written entirely in English.
- Write it as a detailed, production-quality prompt.

VISUAL DEMOGRAPHICS:
- IF the topic requires people, explicitly depict authentic Vietnamese subjects appropriate to the specific context of the prompt.
- Avoid exaggerated cultural stereotypes.
- Do NOT force the inclusion of people if the topic or reference image is better suited for a landscape, object, graphic, or abstract composition.

VISUAL AESTHETIC:
- TEXT CONSTRAINT: Do NOT generate ANY text, words, catchphrases, labels, character names, or watermarks in the image UNLESS the human explicitly requests text in the brief or the prompt. If the user explicitly asks for text, render exactly what they requested. Otherwise, the image must be purely visual without any text overlay.
- IF the user provided a reference image in the prompt, Agent 3 MUST closely analyze its visual style, aesthetic, vibe, color palette, lighting, mood, and composition. Instruct the image generator to MATCH THAT EXACT STYLE seamlessly.
- OTHERWISE (if no reference image is provided), freely determine the most impactful, scroll-stopping, and appropriate visual aesthetic based ENTIRELY on the context of the social-media angle and caption. Do NOT default to "office workers" unless the topic is specifically about corporate office life. Be creative, highly contextual, and match the emotional tone of the post (e.g., dramatic, comedic, cinematic, cozy, abstract, hyper-realistic, etc.).

CRITICAL OUTPUT FORMAT:
- Respond ONLY with one strict, valid JSON object.
- Do NOT use Markdown code fences.
- Do NOT add explanations, comments, labels, or conversational text before or after the JSON.
- Return exactly these three top-level keys and no additional keys.
- All values MUST be JSON strings.
- Ensure all internal quotation marks and special characters are correctly escaped.

{
  "agent_1_research_packet": "Nội dung phân tích và góc khai thác social...",
  "agent_2_publish_ready_caption": "Hook hấp dẫn...\\n\\nNội dung...\\n\\nCall to action...",
  "agent_3_image_prompt": "A detailed production-quality image-generation prompt in English..."
}
`;

return { json: { prompt: prompt, item: ideaItem, providedImageUrl, tenant_id: ideaItem.organization_id, organization_id: ideaItem.organization_id } };

const staticData = $getWorkflowStaticData('node');
staticData.pollCount = (staticData.pollCount || 0) + 1;
if (staticData.pollCount > 120) {
  let threadId = 'unknown';
  try { threadId = $('Webhook Trigger').first().json.body.threadId || $('Webhook Trigger').first().json.threadId; } catch(e) {}
  throw new Error('POLL_TIMEOUT|' + threadId + '|Image generation took too long');
}
return $input.all();

let threadId = null;
let contentItemId = 'unknown';
let workflowRunId = null;
let errorMsg = $('Error Trigger').first().json.execution?.error?.message || 'Unknown Error';

try {
  const dbContextList = $('Load Workflow Context').first().json;
  if (dbContextList && dbContextList.length > 0) {
    const dbContext = dbContextList[0];
    if (dbContext.thread_id) threadId = dbContext.thread_id;
    if (dbContext.content_item_id) contentItemId = dbContext.content_item_id;
    if (dbContext.workflow_run_id) workflowRunId = dbContext.workflow_run_id;
  }
} catch(e) {}

const bodyStr = '❌ **Tạo bài viết thất bại!**\n\nHệ thống gặp lỗi:\n*' + errorMsg + '*\n\nVui lòng thử lại sau.';

return {
  json: {
    p_thread_id: threadId || '00000000-0000-0000-0000-000000000000',
    p_idempotency_key: 'err_' + workflowRunId,
    p_sender: 'system',
    p_intent_type: 'notify_error',
    p_content: bodyStr,
    p_metadata: { contentItemId }
  }
};

const item = $json;
item.r2_url = $('Format Prompt').first().json.providedImageUrl;
if (!item.artifacts) item.artifacts = {};
item.artifacts.image = item.r2_url;
return { json: item };

const body = $input.first().json.body || $input.first().json;
const workflow_run_id = body.workflow_run_id;
const organization_id = body.organization_id;
const thread_id = body.threadId || body.thread_id;
const content_item_id = body.contentItemId || body.content_item_id || body.id || 'unknown';

try { $execution.customData.set('workflow_run_id', workflow_run_id); } catch(e) {}

return { json: { ...$input.first().json, workflow_run_id, organization_id, thread_id, content_item_id } };
